/// <summary>
/// MPJ_30779_PaymentPlus capture exception
/// </summary>
[ExtensionOf(classStr(Global))]
final static class METGlobalCls_Extension
{
}

Method.Source:
    /// <summary>
    /// Get error from infolog and CLR error
    /// </summary>
    /// <returns>A string concatenating both errors</returns>
    public static str METGetErrorAndCLR()
    {
        System.Exception            exception;
        SysInfologEnumerator        enumerator;
        SysInfologMessageStruct     msgStruct;
        Exception                   exceptionLocal;
        str                         errorMessage, errorMessageCLR;
            
        // Get error message from infolog
        enumerator = SysInfologEnumerator::newData(infolog.cut());

        while (enumerator.moveNext())
        {
            msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
            exceptionLocal = enumerator.currentException();

            if (exceptionLocal == Exception::Error)
            {
                errorMessage = strfmt('@MET:ElectrAddrs', errorMessage, msgStruct.message());
                    
            }
        }
           
        // get CLR error if any
        exception = ClrInterop::getLastException();
        if (exception != null)
        {
            errorMessageCLR = exception.get_InnerException() ? exception.get_InnerException().get_Message() : exception.get_Message();
            errorMessage = strfmt(METConstants::TwoStrFmt, errorMessage, errorMessageCLR);
        }

        return errorMessage;
    }

    /// <summary>
    /// CB501_ISP_Security
    /// </summary>
    /// <param name="_userId">
    /// user id to check, default value to current user id
    /// </param>
    /// <returns>true if the current user has METISPXDS security role; otherwise false.</returns>
    public static boolean METisISPUser(UserId _userId = curUserId())
    {
        // Not using a parameter as the AOT name of the role will not changed over time
        const str ISPXDSRole = 'METISPXDS';

        return SysUserManagement::userHasRole(_userId, ISPXDSRole);
    }

    /// <summary>
    /// Method to be used to copy data with common fields from table to table
    /// </summary>
    /// <param name = "_from">From source table</param>
    /// <param name = "_to">To target table</param>
    public static void METtablebufTobuf(Common  _from, Common  _to)
    {
        DictTable   dictTableFrom   = new DictTable(_from.TableId);
        DictTable   dictTableTo     = new DictTable(_to.TableId);
        DictField   dictFieldFrom;
        FieldId     fieldIdFrom     = dictTableFrom.fieldNext(0);
        FieldId     fieldIdTo;

        while (fieldIdFrom && ! isSysId(fieldIdFrom))
        {
            dictFieldFrom   = new DictField(_from.TableId, fieldIdFrom);

            if(dictFieldFrom)
            {
                fieldIdTo = dictTableTo.fieldName2Id(dictFieldFrom.name());

                if(fieldIdTo)
                {
                    _to.(fieldIdTo) = _from.(fieldIdFrom);
                }
            }

            fieldIdFrom = dictTableFrom.fieldNext(fieldIdFrom);
        }
    }
